234	   *  This intentionally overwrites manual per-lot edits — the per-lot
235	   *  picker is for fine-tuning AFTER the total is set.
236	   *
237	   *  When the user instead drives the per-lot picker, we sync `qty` to
238	   *  the new sum (see syncQtyFromAllocation). That sync would otherwise
239	   *  trigger this effect and overwrite their lot edit; the ref below
240	   *  swallows exactly one re-suggest pass to break the loop. */
241	  const skipNextFefoRecalc = useRef(false);
242	  useEffect(() => {
243	    if (availability.length === 0) return;
244	    if (skipNextFefoRecalc.current) {
245	      skipNextFefoRecalc.current = false;
246	      return;
247	    }
248	    setAllocation(suggestFEFO(availability, qty));
249	    // eslint-disable-next-line react-hooks/exhaustive-deps
250	  }, [qty]);
251	
252	  /** Per-lot edit handler — keeps the "How many?" stepper in lockstep
253	   *  with the sum of per-lot takes. Without this, the two surfaces drift:
254	   *  the upper stepper says "1" while the picker says "Taken 4 of 1". */
255	  const onAllocationChange = useCallback(
256	    (next: typeof allocation) => {
257	      const sum = next.reduce((s, l) => s + (l.take || 0), 0);
258	      if (sum !== qty) {
259	        skipNextFefoRecalc.current = true;
260	        setQty(sum);
261	      }
262	      setAllocation(next);
263	    },
264	    [qty, allocation],
265	  );
