267	  const submit = async () => {
268	    if (!selected || totalTaken <= 0) return;
269	    const session = getSession();
270	    setSaving(true);
271	    try {
272	      const picks = allocation
273	        .filter((l) => l.take > 0)
274	        .map((l) => ({ expiry_date: l.expiry, qty: l.take }));
