276	        id: `dsp_${nanoid(12)}`,
277	        barcode: selected.barcode,
278	        product_name: selected.name,
279	        qty: totalTaken,
280	        // Soft-nudge model: server records what the guard actually
281	        // picked rather than enforcing FEFO. Empty picks → server
282	        // falls back to FEFO (the suggestion the user accepted).
283	        lot_picks: picks,
