1	import { CalendarDays, CalendarOff, Trash2, X } from 'lucide-react-native';
2	import React, { useMemo, useState } from 'react';
3	import { Pressable, StyleSheet, TextInput, View } from 'react-native';
4	import { CompactStepper, radius, spacing, Text } from '../../../design';
5	import { useT } from '../../../i18n';
6	import { useTheme } from '../../../theme';
7	import { haptic } from '../../../utils/haptics';
8	import {
9	  compareExpiryAsc,
10	  expiryUrgency,
11	  formatExpiry,
12	  relativeExpiry,
13	  urgencyColors,
14	} from '../../../utils/expiry';
15	import { DatePickerModal } from './DatePickerModal';
16	
17	export type Batch = {
18	  /** Tri-state:
19	   *    string    = ISO YYYY-MM-DD date
20	   *    null      = guard explicitly chose "no expiry"
21	   *    undefined = unset; both chips ("Pick expiry" / "No expiry") shown
22	   *  Downstream code that just needs "is there an expiry date" can keep
23	   *  using a truthy check; submit paths should coerce undefined → null. */
24	  expiry: string | null | undefined;
25	  qty: number;
26	};
27	
28	function toISO(d: Date): string {
29	  return d.toISOString().split('T')[0];
30	}
31	
32	/**
33	 * Edits a list of per-expiry batches for receiving / corrections. Each
34	 * row carries `{qty, expiry}`. Expiry has one combined control:
35	 *   - Unset → two chips: "Pick date" (opens picker) and "No expiry".
36	 *   - Set   → a single urgency-colored chip (date · relative time · ×).
37	 *
38	 * Batches sort by expiry ascending (earliest first, no-expiry last) at
39	 * render time, so the visual order matches FEFO consumption. The caller's
40	 * source-of-truth list also gets the sort whenever a date is picked.
41	 */
42	export function BatchEditor({
43	  batches,
44	  onChange,
45	  minDate,
46	  unit,
47	  packSize,
48	  dispenseMode = 'pack',
49	}: {
50	  batches: Batch[];
51	  onChange: (next: Batch[]) => void;
52	  minDate?: Date;
53	  /** Base unit string, e.g. "g". */
54	  unit?: string | null;
55	  /** Pack size — needed to render "2 × 500 g" (pack mode) vs raw unit
56	   *  (divisible). When omitted, falls back to bare qty + unit. */
57	  packSize?: number | null;
58	  /** 'pack' → integer CompactStepper. 'divisible' → decimal TextInput
59	   *  in base units (e.g. kg, ml). */
60	  dispenseMode?: 'pack' | 'divisible';
61	}) {
62	  const t = useT();
63	  const { palette } = useTheme();
64	  const [editingIdx, setEditingIdx] = useState<number | null>(null);
65	  const divisible = dispenseMode === 'divisible';
66	
67	  // Auto-sort by expiry (earliest first, null last). Caller still owns
68	  // the array; we just present it FEFO-ordered.
69	  const sortedBatches = useMemo(
70	    () =>
71	      batches
72	        .map((b, originalIdx) => ({ b, originalIdx }))
73	        .sort((a, z) => compareExpiryAsc(a.b.expiry, z.b.expiry)),
74	    [batches],
75	  );
76	
77	  const total = batches.reduce((s, b) => s + (b.qty || 0), 0);
78	  const ps = packSize ?? null;
79	  const usePackForm = !divisible && ps != null && ps !== 1;
80	  const totalDisplay = divisible
81	    ? (Math.round(total * 1000) / 1000).toString()
82	    : String(total);
83	  const totalSuffix = usePackForm
84	    ? ` × ${ps}${unit ? ` ${unit}` : ''}`
85	    : unit ? ` ${unit}` : '';
86	
87	  const updateByOriginal = (originalIdx: number, next: Partial<Batch>) => {
88	    const merged = batches.map((b, idx) => (idx === originalIdx ? { ...b, ...next } : b));
89	    onChange(merged);
90	  };
91	  const removeByOriginal = (originalIdx: number) => {
92	    haptic.tap();
93	    onChange(batches.filter((_, idx) => idx !== originalIdx));
94	  };
95	  const add = () => {
96	    haptic.tap();
97	    // undefined = unset; both chips visible. Forces a deliberate choice
98	    // instead of silently defaulting to "no expiry".
99	    onChange([...batches, { qty: divisible ? 0 : 1, expiry: undefined }]);
100	  };
101	
102	  const labelForRowNumber = (visualIdx: number) => `#${visualIdx + 1}`;
103	
104	  return (
105	    <View style={{ gap: spacing.sm }}>
106	      <View
107	        style={{
108	          flexDirection: 'row',
109	          justifyContent: 'space-between',
110	          alignItems: 'baseline',
111	        }}
112	      >
113	        <Text variant="labelLarge" color={palette.onSurfaceVariant}>
114	          {t('batches').toUpperCase()}
115	        </Text>
116	        <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
117	          {t('totalLabel')}: {totalDisplay}{totalSuffix}
118	        </Text>
119	      </View>
120	
121	      {sortedBatches.map(({ b, originalIdx }, visualIdx) => {
122	        const urgency = expiryUrgency(b.expiry);
123	        const colors = urgencyColors(urgency, palette);
124	        const canRemove = batches.length > 1;
125	        return (
126	          <View
127	            key={originalIdx}
128	            style={[
129	              styles.card,
130	              {
131	                backgroundColor: palette.surfaceContainerLowest,
132	                borderColor: palette.outlineVariant,
133	              },
134	            ]}
135	          >
136	            {/* ─── Left rail: batch number, centered ─── */}
137	            <View
138	              style={[
139	                styles.rail,
140	                styles.leftRail,
141	                {
142	                  backgroundColor: palette.surfaceContainerLow,
143	                  borderRightColor: palette.outlineVariant,
144	                },
145	              ]}
146	            >
147	              <Text
148	                variant="titleMedium"
149	                color={palette.onSurfaceVariant}
150	                style={{ fontWeight: '700' }}
151	              >
152	                {visualIdx + 1}
153	              </Text>
154	            </View>
155	
156	            {/* ─── Middle: the actual fields ─── */}
157	            <View style={styles.middle}>
158	              {/* Qty section */}
159	              <View style={{ gap: spacing.xs }}>
160	                <Text variant="labelMedium" color={palette.onSurfaceVariant} style={styles.sectionLabel}>
161	                  HOW MANY?
162	                </Text>
163	                {divisible ? (
164	                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.xs }}>
165	                    <TextInput
166	                      value={b.qty === 0 ? '' : String(b.qty)}
167	                      onChangeText={(txt) => {
168	                        const cleaned = txt.replace(/[^0-9.]/g, '');
169	                        const n = cleaned === '' || cleaned === '.' ? 0 : Number(cleaned);
170	                        updateByOriginal(originalIdx, { qty: Number.isFinite(n) ? n : 0 });
171	                      }}
172	                      keyboardType="decimal-pad"
173	                      placeholder="0"
174	                      placeholderTextColor={palette.onSurfaceVariant}
175	                      style={[
176	                        styles.decimalInput,
177	                        {
178	                          borderColor: palette.outline,
179	                          color: palette.onSurface,
180	                          backgroundColor: palette.surface,
181	                        },
182	                      ]}
183	                    />
184	                    {unit ? (
185	                      <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
186	                        {unit}
187	                      </Text>
188	                    ) : null}
189	                  </View>
190	                ) : (
