          onPress={startEdit}
          android_ripple={{ color: palette.outlineVariant, borderless: true }}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
        >
          <Text variant="displayLarge" style={styles.qtyText}>
